#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    long long n;
    cin >> n;
    vector<long long> h(n);
    for (int i = 0; i < n; i++) cin >> h[i];

    int l = 0, rr = n - 1;
    long long leftMax = 0, rightMax = 0, water = 0;
    while (l < rr) {
        if (h[l] < h[rr]) {
            leftMax = max(leftMax, h[l]);
            water += leftMax - h[l];
            l++;
        } else {
            rightMax = max(rightMax, h[rr]);
            water += rightMax - h[rr];
            rr--;
        }
    }
    cout << water << "\n";

    return 0;
}

